"""Full carrot methods and their recovered sauce components."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'carrot-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def carrot(a):return I('carrot',a,'g','carrots, peeled and trimmed','Use the same weight of a different carrot variety; color and sweetness will change.')
def butter(a):return I('butter',a,'g','unsalted butter','Use the same weight of a block-style dairy-free butter alternative.')
def stock(a):return I('stock',a,'ml','unsalted prepared beef stock','Use the same volume of unsalted vegetable stock for a different flavor; check other ingredients before treating the whole recipe as vegetarian.')
def onion(a):return I('onion',a,'g','peeled onion','Use the same weight of trimmed leek, rinsing away any grit.')
def salt(a=3):return I('salt',a,'g','fine salt','Reduce or omit, especially if using salted stock.')
def pepper():return I('pepper',.25,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def cayenne():return I('cayenne',.125,'tsp','ground cayenne pepper','Omit for a milder soup.')
def sugar(a):return I('sugar',a,'g','granulated sugar','Use the same weight of caster sugar.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water; water for dough or starch slurry should remain cold.')
def flour(a):return I('flour',a,'g','all-purpose flour','For a sauce, use the same weight of a gluten-free blend labeled for sauces; pastry requires a separate tested gluten-free dough.')
def bread(a):return I('bread',a,'g','plain bread','Use the same weight of gluten-free bread suitable for toasting.')
def oil(a,k='oil'):return I(k,a,'ml','neutral vegetable oil','Use the same volume of refined sunflower or rapeseed oil.')
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g pasteurized liquid yolk per large yolk; omitting yolk changes the recipe.')
def cream(a):return I('cream',a,'ml','heavy cream','Use the same volume of unsweetened plant cream suitable for cooking.')
def celery(a):return I('celery',a,'g','trimmed celery stalks','Use the same weight of peeled celeriac, cut small and cooked until tender.')
def turnip(a):return I('turnip',a,'g','peeled turnip','Use the same weight of peeled rutabaga; allow extra cooking time until tender.')
def add(n,title,y,t,desc,items,steps,notes,category='Side dishes'):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category=category,servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T18:00:00Z',notes=notes+' Missing amounts, yields and timings are modern adaptation estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes quantities, not cooking times. Cool leftovers promptly in shallow containers and refrigerate within 2 hours at 4°C (40°F) or colder.',source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
PUREE='Press the vegetables and their liquid through a coarse sieve into a clean saucepan, or use an immersion blender directly in the deep pan with its head submerged. Do not seal hot soup in a countertop blender.'
def parsley(a=5):return I('parsley',a,'g','fresh parsley, finely chopped','Use the same weight of chives, or omit.')
def milk(a):return I('milk',a,'ml','whole milk','Use the same volume of unsweetened soy milk; flavor differs.')
def rice(a):return I('rice',a,'g','uncooked long-grain white rice','Use the same weight of another white rice; follow its cooking time until tender.')
def eggfinish():return ['Whisk {{yolks}} with {{cream}} in a bowl. Gradually whisk in a little hot soup, then return the mixture to the saucepan.','Stir over low heat until the soup reaches 71°C (160°F), without boiling. Serve promptly.']
def lemon(a,k='lemon'):return I(k,a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
def bay():return I('bay',1,'','dried bay leaf','Omit if unavailable.')
def lard(a):return I('lard',a,'g','food-grade pork lard','Use the same weight of neutral vegetable oil.')
def tk(k):return '{{'+k+'}}'
def roux(prefix,b,f,liquid,liquidname='unsalted prepared chicken stock'):
 return [dict(butter(b),key=prefix+'butter'),dict(flour(f),key=prefix+'flour'),I(prefix+'stock',liquid,'ml',liquidname,'Use the same volume of unsalted vegetable stock; flavor differs.')]
def rouxsteps(p):
 return ['In a separate small saucepan, melt '+tk(p+'butter')+'. Stir in '+tk(p+'flour')+' and cook for 2 minutes without browning. Gradually whisk in '+tk(p+'stock')+' until smooth. Simmer gently for 5 minutes, stirring.']
def veloute(prefix='s',volume=120):
 # A small complete mushroom sauce component, with all output used in its parent.
 q=volume/120
 return roux(prefix,10*q,8*q,120*q)+[I(prefix+'mushroom',25*q,'g','cultivated white mushrooms, finely chopped','Use the same weight of cultivated cremini mushrooms.')]
def veloutesteps(p='s'):
 return ['Melt '+tk(p+'butter')+' in a small pan. Add '+tk(p+'mushroom')+' and cook gently for 5 minutes without browning. Stir in '+tk(p+'flour')+' for 2 minutes, then gradually whisk in '+tk(p+'stock')+'. Simmer for 10 minutes, stirring, until smooth. Press through a fine sieve, discard the mushroom pieces and keep the sauce warm.']

def peas(a):return I('peas',a,'g','shelled green peas, fresh or frozen','Use the same weight of frozen peas, adding them without thawing.')
def cornflour(a):return I('cornflour',a,'g','cornstarch (cornflour)','Use the same weight of arrowroot starch, adding it near the end and heating just until thickened.')
def nutmeg():return I('nutmeg',.125,'tsp','ground nutmeg','Use the same amount of ground mace, or omit.')
def boilsteps(shape='1 cm cubes',time='12–18'):
 return ['Cut {{carrot}} into '+shape+'. Bring {{water}} and {{salt}} to a boil. Add the carrots and simmer for '+time+' minutes until tender when pierced with a fork. Drain well.']

def eggs(a):return I('eggs',a,'','large eggs','Use 50 g pasteurized liquid whole egg per egg when separation is not required.')
def crumbs(a):return I('crumbs',a,'g','plain dry breadcrumbs','Use the same weight of dry crumbs from another plain wheat bread.')
def almond(a):return I('almond',a,'g','finely ground blanched almonds','Use the same weight of finely ground sunflower seeds for a different flavor.')
def grease():return I('grease',5,'g','softened unsalted butter for the dish','Use the same weight of a block-style dairy-free butter alternative.')
def peel(a):return I('peel',a,'g','thin yellow lemon peel, white pith removed, finely shredded','Use the same weight of thin orange peel for a different flavor.')
def separated(r):next(i for i in r['ingredients'] if i['key']=='eggs')['substitution']='Use large pasteurized shell eggs if preferred; the whites must remain separate and able to whip.'
CHILL='Transfer to clean shallow food-safe containers. Cool promptly, cover and refrigerate within 2 hours at 4°C (40°F) or colder. Use within 4 days, or freeze promptly. This is not shelf-stable and must not be stored at room temperature.'

r=add(51,'Gulerods-Marmelade (Refrigerated Carrot-Lemon Jam)',32,75,'Smooth carrot purée cooks with sugar, lemon juice and fine strips of lemon peel into a bright, spoonable jam.',[carrot(750),water(350),sugar(500),lemon(120),peel(12)],['Slice {{carrot}} thinly and put in a saucepan with {{water}}. Cover and simmer for 15–20 minutes until very soft, adding a little water if the pan dries.','Press the carrots and their cooking liquid through a sieve or food mill into a wide saucepan. Add {{sugar}}, {{lemon}} and {{peel}}.','Bring to a gentle boil, stirring until the sugar dissolves. Cook uncovered for 20–35 minutes, stirring frequently and then constantly as it thickens, until a spoon drawn across the pan leaves a brief clear trail. The texture is a thick spread, not a firm jelly.',CHILL],'The original scan gives 500 g sugar for 750 g carrots, not the incorrect extracted 333 g sugar for 250 g carrots. Juice from four lemons and peel from two become modern 120 ml and 12 g. Water, cooking times and small serving yield are supplied. Refrigeration/freezing replaces paper-covered room-temperature storage.','Preserves')
r['source']+=' Primary scan verified: Frøken Jensens kogebog recipe 130, printed page 342, leaf 354.'

r=add(52,'Gulerødder in Lemon Syrup (Refrigerated)',30,70,'Fine carrot strips and lemon peel are coated in a concentrated lemon-sugar syrup.',[carrot(500),peel(6),water(800),sugar(500),I('reservedwater',250,'ml','reserved carrot cooking water from the steps','Use the same volume of fresh drinking water if needed.'),lemon(90)],['Cut {{carrot}} into fine matchsticks about 2–3 mm thick. Put in a saucepan with {{peel}} and {{water}}, cover and simmer for 10–15 minutes until tender but intact.','Drain into a bowl and measure {{reservedwater}} from the liquid. Put that measured liquid in a clean saucepan with {{sugar}} and {{lemon}}. Bring to a gentle boil, stirring until dissolved.','Add the drained carrots and peel and simmer for 5–6 minutes. Lift them out into a sieve set over a bowl, then return all drained syrup to the pan.','Boil the syrup gently for 10–15 minutes until it lightly coats a spoon. Watch closely so it does not darken or burn. Return the carrots and peel to the syrup and heat for 1 minute, turning gently.',CHILL],'The source half-kilogram amounts and quarter-liter cooking liquid are retained. Urtevandet is the carrot cooking water, not a separate herb infusion. Juice from three lemons becomes 90 ml and peel from one becomes 6 g. The strained second syrup reduction remains. Storage is refrigerated/frozen rather than a paper-tied jar on a shelf.','Preserves')

r=add(54,'Karotter (Refrigerator-Pickled Carrots)',12,1530,'Small carrots steep with white pepper and chile in a sharp vinegar pickle, with the vinegar reheated the following day.',[carrot(600),water(1500),I('vinegar',600,'ml','commercial white wine vinegar labeled 5% acidity','Use the same volume of commercial cider vinegar labeled 5% acidity.'),I('peppercorns',1,'tsp','whole white peppercorns','Use the same amount of whole black peppercorns.'),I('chile',1,'','small dried red chile, stem removed','Omit for a milder pickle.')],['Choose slender {{carrot}} and leave them whole, or halve thick carrots lengthwise. Bring {{water}} to a boil, add the carrots and simmer for 5–8 minutes until partly tender.','Drain, rinse briefly under cold drinking water and pat dry with a clean towel. Pack in clean heatproof jars or containers with {{peppercorns}} and {{chile}}.','Pour {{vinegar}} over the carrots, using a narrow enough container to keep them submerged. Cover and refrigerate at 4°C (40°F) or colder for 24 hours.','Drain the vinegar into a saucepan, keeping the carrots refrigerated while it heats. Bring the vinegar to a boil, then carefully pour it over the carrots in heatproof containers. Let cool briefly and refrigerate within 2 hours.','Keep refrigerated and use within 4 days of the first preparation, including the overnight steep. Serve small portions, removing the whole chile and peppercorns if desired.'],'All amounts are modern choices. Spanish pepper husks are interpreted as a small dried chile; the source straight-vinegar character is retained. The overnight stage takes place in the refrigerator and shelf storage is not claimed. This is not a tested canning recipe. Total time includes the overnight steep.','Preserves')

r=add(55,'Omelet med Gulerødder (Fluffy Carrot Omelet)',4,50,'A folded egg-white omelet encloses buttered carrots and parsley, with a little whipped butter alongside.',[eggs(5),milk(150),salt(2),butter(55),carrot(300),water(1000),parsley(5)],['Slice {{carrot}} into 5 mm rounds. Bring {{water}} to a boil and cook the carrots for 10–15 minutes until tender. Drain and toss with {{butter|0.2727272727272727}} in a small saucepan over low heat. Keep warm.','Separate {{eggs}}, putting the whites in a clean grease-free bowl. Beat the yolks with {{milk}} and {{salt}}. Beat the whites to firm peaks and fold gently into the yolks.','Melt {{butter|0.45454545454545453}} in a wide nonstick skillet over low-medium heat. Pour in the egg mixture, gently lift the edges to let unset egg move underneath, then cover and cook over low heat for 8–12 minutes until the top is set and the center reaches 71°C (160°F). Do not flip.','Place the warm buttered carrots along the middle, sprinkle with {{parsley}} and fold the omelet over the filling.','Beat softened {{butter|0.2727272727272727}} with a spoon until light. Serve a small amount beside each portion of the omelet.'],'The ten tablespoons of milk become 150 ml. Five whites are matched to the five source yolks. Butter is divided between carrots, pan and the stirred-butter accompaniment. A lid helps set the top without turning; pan size, heat and thermometer endpoint are supplied.')
separated(r)
variant(r,'cream','Cream omelet with carrots',[dict(i,name='light cream (about 18% fat)',substitution='Use the milk base for a lighter omelet.') if i['key']=='milk' else copy.deepcopy(i) for i in r['ingredients']],copy.deepcopy(r['steps']))
kitems=[dict(i,name='trimmed kale leaves, tough stalks removed',substitution='Use the carrot base version instead.') if i['key']=='carrot' else copy.deepcopy(i) for i in r['ingredients']]
ksteps=copy.deepcopy(r['steps']);ksteps[0]='Bring {{water}} to a boil, add {{carrot}} and cook for 5–8 minutes until tender. Drain, squeeze out excess water, chop finely and toss with {{butter|0.2727272727272727}} in a small saucepan over low heat. Keep warm.';ksteps[3]=ksteps[3].replace('carrots','kale')
variant(r,'kale','Fluffy kale omelet',kitems,ksteps)

r=add(102,'Porkkana-Putinki (Carrot and Almond Pudding)',8,110,'Mashed carrots bake with breadcrumbs, milk and a little almond into a softly set savory pudding.',[carrot(900),water(1500),crumbs(180),sugar(19),milk(480),salt(4),butter(42),almond(25),eggs(2),grease()],['Cut {{carrot}} into 1 cm pieces. Bring {{water}} to a boil and simmer the carrots for 15–20 minutes until very tender. Drain, mash smoothly and spread in a shallow bowl to cool until no longer warm.','Heat the oven to 160°C (320°F). Grease a 2-liter baking dish with {{grease}}. Mix {{crumbs}}, {{sugar}}, {{milk}}, {{salt}}, melted {{butter}} and {{almond}} into the cooled carrot mash.','Beat {{eggs}} and stir into the mixture. Pour into the prepared dish and place it in a roasting pan. Pour hot water into the roasting pan until it reaches halfway up the outside of the dish.','Bake for 55–70 minutes until set in the center and at least 71°C (160°F). Lift the dish carefully from the water bath, rest for 10 minutes and serve in the dish.'],'The primary scan gives one-quarter cup almonds, not the extracted three-quarters. Its 1½ tablespoons of sugar become 19 g. Two pounds of carrots, cups of crumbs and milk become modern 900 g, 180 g and 480 ml choices; salt is moderated to 4 g. Water-bath baking gives a gentle finish. The later book version with less sugar and grated cooked carrot is retained as a named variation.')
variant(r,'cream','Carrot pudding with cream',[dict(i,name='light cream (about 18% fat)',substitution='Use the milk base for a lighter pudding.') if i['key']=='milk' else copy.deepcopy(i) for i in r['ingredients']],copy.deepcopy(r['steps']))
vitems=[dict(i,amount=13) if i['key']=='sugar' else copy.deepcopy(i) for i in r['ingredients']];vsteps=copy.deepcopy(r['steps']);vsteps[0]='Put {{carrot}} whole in a saucepan with {{water}}, bring to a simmer and cook for 20–30 minutes until tender. Drain and let cool until safe to handle, then grate and let cool until no longer warm.';vsteps[1]=vsteps[1].replace('carrot mash','grated carrot')
variant(r,'later-grated','Less-sweet grated-carrot version',vitems,vsteps)
vsteps=copy.deepcopy(r['steps']);vsteps[2]='Beat {{eggs}} and stir into the mixture. Pour into the prepared baking dish.';vsteps[3]='Bake directly on the oven shelf for 45–60 minutes until set and at least 71°C (160°F) in the center. Rest for 10 minutes and serve in the dish.'
variant(r,'direct-bake','Direct oven bake',copy.deepcopy(r['ingredients']),vsteps)
r['source']+=' Primary scans compared: 1914 book page 130 (leaf 136) and 1928 recipe 405 page 163 (leaf 167).'

r=add(107,'Porkkanaputinki Riisin Kanssa (Carrot-Rice Pudding)',8,140,'Creamy rice porridge and grated carrots bake together with a little almond, butter and egg.',[I('rice',180,'g','uncooked short-grain white rice','Use the same weight of another white pudding rice, cooking until soft.'),water(720),milk(480),carrot(450),water(1000,'carrotwater'),almond(8),salt(4),sugar(6.5),eggs(1),butter(28),grease()],['Put {{rice}} and {{water}} in a heavy saucepan. Bring to a simmer and cook for 10 minutes. Add {{milk}} and cook over low heat for 20–30 minutes, stirring often, until the rice is soft and the mixture resembles thick porridge. Add a little water if it dries before the rice softens.','Meanwhile, put {{carrot}} whole in a second saucepan with {{carrotwater}}. Bring to a simmer and cook for 15–25 minutes until nearly tender. Drain, let cool until safe to handle and grate.','Stir the grated carrot, {{almond}}, {{salt}}, {{sugar}} and {{butter}} into the porridge. Spread in a shallow bowl and cool until no longer warm, then beat in {{eggs}}.','Heat the oven to 175°C (350°F). Grease a 2-liter baking dish with {{grease}}, add the mixture and bake for 50–60 minutes until set, lightly golden and at least 71°C (160°F) in the center. Rest for 10 minutes and serve.'],'Both original page scans give HALF a tablespoon of sugar. The apparent 1½ tablespoon difference is an extraction error, so the duplicate is consolidated. A modern cup is 240 ml for water and the pint of milk becomes 480 ml; dry rice is weighed at 180 g. The large source salt spoon is deliberately reduced to 4 g. Full porridge preparation and cooling before egg addition are supplied.')
r['source']+=' Primary scans verified: 1928 recipe 404 page 162 (leaf 166) and 1914 book page 130 (leaf 136).'

for n,title,c,f in [(104,'Porkkana-Tippoja (Creamy Carrot Fritters)',85,85),(110,'Porkkanatippoja (Light Carrot Fritters)',42,48)]:
 items=[carrot(220),eggs(4),cream(240),crumbs(c),flour(f),butter(56),salt(2),oil(300,'fryoil')]
 steps=['Finely grate {{carrot}}. Separate {{eggs}}, keeping the whites in a clean grease-free bowl. Beat the yolks with {{cream}}, melted and cooled {{butter}} and {{salt}}.','Stir in the grated carrot, {{crumbs}} and {{flour}}. Let stand for 10 minutes so the crumbs absorb liquid. Beat the reserved whites to firm peaks and fold gently into the batter.','Heat {{fryoil}} in a deep skillet to 165–175°C (330–350°F), keeping oil below one-third of the pan depth. Drop small spoonfuls of batter into the oil, leaving room between them, and flatten gently to about 1 cm thick.','Fry for 3–4 minutes per side until golden, the fine carrot shreds are tender and the center reaches 71°C (160°F). Adjust the heat if the outside browns before the middle sets. Drain on a rack and serve immediately.']
 r=add(n,title,8,50,'Fine raw carrot shreds are folded into an egg-white batter with '+('a generous amount of breadcrumbs and flour' if n==104 else 'a small amount of breadcrumbs and flour')+', then fried into tender golden fritters.',items,steps,('The Finnish source gives three ounces EACH of crumbs and flour, converted to 85 g each.' if n==104 else 'Six source tablespoons each of crumbs and flour become chosen weights of 42 g and 48 g, not the heavier three-ounce formula.')+' Two cups of grated carrot become 220 g and a cup of cream becomes 240 ml. Frying oil and controlled temperature replace the phrase boiling fat. Oil is the pan quantity, not the amount absorbed. Keep small fritters for even cooking.')
 separated(r);next(i for i in r['ingredients'] if i['key']=='flour')['substitution']='Use the same weight of plain wheat pastry flour; a gluten-free batter would require separate development.'
 if n==110:variant(r,'milk','Milk-based light fritters',[dict(i,name='whole milk',substitution='Use the cream base for a richer batter.') if i['key']=='cream' else copy.deepcopy(i) for i in r['ingredients']],copy.deepcopy(r['steps']))

r=add(111,'Porkkanatippoja (Cooked-Carrot Fritters)',4,55,'Smooth cooked carrot purée and beaten egg whites make delicate, lightly floured fritters browned in butter.',[carrot(400),water(1000),flour(16),eggs(2),butter(50)],['Cut {{carrot}} into 1 cm pieces. Bring {{water}} to a boil and simmer the carrots for 15–20 minutes until very tender. Drain thoroughly and return to the warm empty pan for 1–2 minutes to remove surface moisture.','Press the carrots through a sieve and let cool until no longer warm. Separate {{eggs}}, beat the yolks and stir them into the carrot purée with {{flour}}. Beat the whites to firm peaks and fold in gently.','Melt {{butter}} a little at a time in a nonstick skillet over medium-low heat, reserving some for later batches. Add rounded tablespoonfuls of batter and flatten to about 1 cm thick.','Cook for 3–4 minutes per side until golden and set, with the center reaching 71°C (160°F). Turn carefully with a thin spatula; these are delicate fritters. Serve immediately.'],'Two cups of cooked carrot become a modern 400 g peeled-carrot starting weight, with full boiling and draining instructions supplied. The two tablespoons of flour become 16 g. This cooked-purée formula differs from the raw-carrot, milk-and-breadcrumb fritters and remains separate.')
separated(r);next(i for i in r['ingredients'] if i['key']=='flour')['substitution']='Use the same weight of plain rice flour for a different texture.'

r=add(126,'Morotspudding (Swedish Carrot Pudding)',6,85,'Grated, partly cooked carrots bake with soft bread, milk and eggs under a light rusk-crumb topping.',[carrot(750),water(1500),I('softbread',45,'g','finely grated soft white bread','Use the same weight of finely grated soft wholemeal bread for a different texture.'),butter(28),eggs(2),milk(200),salt(4),I('grease',7,'g','softened butter for the dish','Use the same weight of a block-style dairy-free butter alternative.'),I('rusk',14,'g','finely crushed plain rusks','Use the same weight of plain dry breadcrumbs.')],['Put {{carrot}} whole in a saucepan with {{water}}, bring to a simmer and cook for 10–15 minutes until partly tender. Drain, let cool until safe to handle and grate.','Heat the oven to 175°C (350°F). Grease a 1.5-liter baking dish with {{grease}} and coat with {{rusk|0.5}}.','Beat {{eggs}} with {{milk}}, melted and cooled {{butter}}, {{softbread}} and {{salt}}. Stir in the grated carrot and pour into the prepared dish. Sprinkle with {{rusk|0.5}}.','Bake for 40–50 minutes until set, lightly browned and at least 71°C (160°F) in the center. Rest for 10 minutes, then serve as a vegetable side.'],'The original recipe specifies 2 DECILITERS of milk, exactly 200 ml, not two undefined parts. The 750 g carrots and six-person yield are retained. Bread and rusk spoonfuls are converted to chosen preparation weights; salt is moderated. The duplicate uses breadcrumbs where the original says rusks, retained as an explicit coating choice.')
variant(r,'breadcrumbs','Breadcrumb-coated pudding',[dict(i,name='plain dry breadcrumbs',substitution='Use the rusk base for a crisper coating.') if i['key']=='rusk' else copy.deepcopy(i) for i in r['ingredients']],copy.deepcopy(r['steps']))
r['source']+=' Primary scan verified: Hemmets kokbok recipe 389, printed page 212, leaf 225.'

r=add(4,'Carrot, Orange and Lemon Marmalade (Refrigerated)',20,75,'Carrot purée, orange and lemon cook into a soft citrus spread with fine shreds of peel.',[carrot(450),water(250),salt(1),sugar(200),I('orange',150,'g','peeled orange segments with juice, seeds and tough membranes removed','Use the same weight of peeled mandarin segments and juice.'),I('orangepeel',6,'g','thin orange peel, white pith removed, finely shredded','Use the same weight of thin lemon peel for a sharper flavor.'),lemon(30),peel(6)],['Slice {{carrot}} thinly and put in a saucepan with {{water}} and {{salt}}. Cover and simmer for 15–20 minutes until very tender, adding a little water if needed. Mash with the remaining cooking liquid.','Add {{sugar}}, chopped {{orange}}, {{orangepeel}}, {{lemon}} and {{peel}}. Bring to a gentle boil, stirring until the sugar dissolves.','Cook uncovered for 25–35 minutes, stirring frequently and then constantly as it thickens, until the peel is tender and a spoon drawn through the mixture leaves a brief trail.',CHILL],'The source as-marmalade reference is expanded into a complete cooked spread. Two cups of prepared carrot become a modern 450 g raw starting weight; one cup of sugar becomes 200 g. Orange, lemon and water amounts are explicit modern choices. A finely grated-carrot version preserves the source texture option.','Preserves')
st=copy.deepcopy(r['steps']);st[0]='Finely grate {{carrot}} and put in a saucepan with {{water}} and {{salt}}. Cover and simmer for 10–15 minutes until tender, adding a little water if needed. Keep the fine shreds rather than mashing.'
variant(r,'grated','Grated-carrot marmalade',copy.deepcopy(r['ingredients']),st)

r=add(3,'Spiced Carrot Custard Pie',8,130,'A baked shortcrust shell holds smooth carrot custard seasoned with cinnamon and ginger.',[carrot(450),water(1000),sugar(200),eggs(3),I('cinnamon',1,'tsp','ground cinnamon','Use the same amount of a cinnamon-led baking spice blend.'),I('ginger',1,'tsp','ground ginger','Use half the amount of ground allspice for a different flavor.'),salt(1),I('pastryflour',200,'g','all-purpose flour for the crust','Use the same weight of plain wheat pastry flour.'),I('pastrybutter',100,'g','cold unsalted butter, diced','Use the same weight of a block-style dairy-free butter alternative suitable for pastry.'),water(45,'pastrywater'),I('pastrysalt',1.5,'g','fine salt for the crust','Reduce or omit.'),I('dustflour',10,'g','all-purpose flour for rolling','Use a small amount of rice flour for dusting.')],['Mix {{pastryflour}} with {{pastrysalt}}. Rub in {{pastrybutter}} until the mixture resembles coarse crumbs. Add {{pastrywater}} and bring together without kneading, adding water a teaspoon at a time only if dry. Flatten into a disc, wrap and refrigerate for 30 minutes.','Meanwhile, cut {{carrot}} into 1 cm pieces. Bring {{water}} to a boil and cook the carrots for 15–20 minutes until very tender. Drain thoroughly, mash smoothly and spread in a shallow bowl to cool until no longer warm.','Heat the oven to 190°C (375°F). Roll the chilled pastry on {{dustflour}} to about 3 mm thick and line a 23 cm pie dish. Trim, prick the base, line with baking parchment and fill with reusable baking weights.','Bake for 15 minutes, remove parchment and weights carefully, then bake for 5–8 minutes until the base looks dry. Reduce the oven to 175°C (350°F).','Beat {{eggs}} with {{sugar}}, {{cinnamon}}, {{ginger}} and {{salt}}. Stir into the cooled carrot purée and pour into the warm pastry shell.','Bake for 35–45 minutes until the custard is set with only a slight central wobble and reaches at least 71°C (160°F). Cool on a rack and refrigerate within 2 hours if not serving immediately.'],'The source gives filling but requires an undeclared pie shell; a full modern shortcrust is supplied. Two cups of mashed boiled carrots become a chosen 450 g raw starting weight. Sugar becomes 200 g. Blind baking and a measured oven endpoint replace hot-oven shorthand. This is a single-crust pie with no top crust.','Desserts')

r=add(150,'Carrot Custard with Cinnamon and Rose Water',6,80,'A small amount of smooth carrot purée flavors a rich baked egg custard with butter, cinnamon and rose water.',[carrot(180),water(750),eggs(5),sugar(57),butter(57),I('cinnamon',.25,'tsp','ground cinnamon','Use the same amount of ground nutmeg for a different flavor.'),I('rosewater',2.5,'ml','food-grade culinary rose water','Use the same volume of vanilla extract for a different flavor.'),grease()],['Cut {{carrot}} into small pieces. Bring {{water}} to a boil and simmer the carrots for 15–20 minutes until very tender. Drain thoroughly, press through a sieve and cool until no longer warm.','Heat the oven to 160°C (320°F). Grease a 1-liter baking dish with {{grease}}. Beat {{eggs}} with {{sugar}}, melted and cooled {{butter}}, {{cinnamon}} and {{rosewater}}, then stir in the carrot purée.','Pour into the dish and bake for 30–40 minutes until the center is set and reaches at least 71°C (160°F). If the top browns too quickly, cover loosely with foil.','Rest for 10 minutes before serving. Cool and refrigerate promptly if serving cold.'],'The undefined coffee cup of cooked carrot becomes a modern 180 g raw-carrot starting weight. Two ounces each of sugar and butter become 57 g each. Spice, rose water, dish size and oven settings are supplied. The source specifies a deep dish without pastry, which is retained.','Desserts')

r=add(63,'Worteltjes (Carrots Prepared for the Freezer)',8,60,'Small carrots are briefly blanched, chilled and packed for freezing, ready to finish cooking when needed.',[carrot(1000),water(4000),I('coldwater',4000,'ml','ice-cold drinking water for cooling','Replace with fresh cold water as it warms.'),I('ice',1000,'g','ice made from drinking water','Use additional very cold drinking water, changing it as needed.'),sugar(8),salt(2),water(2000,'cookwater')],['Choose slender young {{carrot}} and leave them whole; slice thicker carrots into 5–6 mm rounds. Bring {{water}} to a rolling boil in a large pot. Mix {{coldwater}} with {{ice}} in a clean large bowl.','Blanch the carrots in small batches: small whole carrots for 5 minutes, sliced carrots for 2 minutes. Start timing when the water returns to a boil; reduce batch size if that takes more than 1 minute.','Transfer immediately to the ice water and cool for about the same time as blanching. Drain very thoroughly, then toss the cold carrots with {{sugar}} and {{salt}}.','Pack in freezer-safe containers or bags, leaving about 1.3 cm (½ inch) headspace in rigid containers. Seal, label with the name, date and amount, and freeze promptly at −18°C (0°F) or colder.','To serve, bring {{cookwater}} to a simmer and cook the frozen carrots until tender, usually 5–10 minutes for slices or 10–15 minutes for small whole carrots. Drain and serve.'],'The two source entries are the same preservation recipe, with a brief pre-cook noted in the longer entry. The unverified 90-minute bottle-sterilizing method is replaced explicitly by freezer preservation using published carrot blanching times. Sugar and salt are small flavor additions, not preservatives. Twelve undefined bunches become a manageable 1 kg batch. This is not a canning recipe and is not shelf-stable; labeling and preserved-carrot use remain part of the preparation.','Preserves')
variant(r,'plain','Plain freezer carrots',[copy.deepcopy(i) for i in r['ingredients'] if i['key'] not in ['sugar','salt']],[t.replace(', then toss the cold carrots with {{sugar}} and {{salt}}','') for t in r['steps']])
r['source']+=' Modern freezer process: https://nchfp.uga.edu/how/freeze/vegetable/freezing-carrots/ .'

merges=[(106,102,'Primary scans have the same quarter-cup almond formula; the later lower-sugar/grated-carrot method is preserved as a full named variation.'),(108,107,'Both original scans show the same half-tablespoon sugar and complete rice-carrot pudding method; the apparent larger sugar quantity is an extraction error.'),(125,126,'The two records transcribe the same source recipe389; original200ml milk restored and breadcrumb/rusk coating choice retained.'),(62,63,'Same whole-carrot preservation formula and bottle method; the longer source adds a brief pre-cook note. Both retained in the disclosed freezer adaptation with whole and sliced blanching instructions.')]
for old,target,reason in merges:
 s=src(old);r=records[rows[target]['id']]['recipe'];r['sourceAliases'].append(s['id']);r['source']+=' Equivalent source retained: '+s['recipe']['source'];aliases[s['id']]=dict(id=s['id'],canonicalId=r['id'],bodySha256=s['bodySha256'],reason=reason)
assert len(newids)==14,len(newids)
for id in newids:
 r=records[id]['recipe']
 if any(i['key']=='eggs' for i in r['ingredients']):r['source']+=' Egg cooking reference: https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-egg-safety .'
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
(root/'recipe-aliases.json').write_text(json.dumps(list(aliases.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full ingredients and methods reviewed; scanned original measurements and complete modern preparation supplied','repair-batch-015.py'))
for old,target,reason in merges:
 id=rows[old]['id'];db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,aliases[id]['bodySha256'],'prepared-merge',reason,'repair-batch-015.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=len(merges),totalOverrides=len(records),totalAliases=len(aliases))))

